  class Process {
    var id: int
    var inbox: seq<Message>
    var outbox: seq<Message>
    var clock: int  // Logical clock for ordering

    constructor(initId: int) 
      ensures id == initId
      ensures inbox == []
      ensures outbox == []
      ensures clock == 0
    {
      id := initId;
      inbox := [];
      outbox := [];
      clock := 0;
    }

    // Send a message to another process
    method Send(content: string, receiverId: int, processes: seq<Process>) 
      returns (success: bool)
      requires |processes| > 0
      requires receiverId >= 0 && receiverId < |processes|
      ensures success ==> processes[receiverId].inbox == old(processes[receiverId].inbox) + [Message(content, id, receiverId, clock)]
      ensures success ==> outbox == old(outbox) + [Message(content, id, receiverId, clock)]
      ensures success ==> clock == old(clock) + 1
    {
      if receiverId < 0 || receiverId >= |processes| {
        success := false;
        return;
      }

      var receiver := processes[receiverId];
      var msg := Message(content, id, receiverId, clock);

      // Update logical clock
      clock := clock + 1;

      // Add to outbox
      outbox := outbox + [msg];

      // Deliver to receiver's inbox
      processes[receiverId].inbox := processes[receiverId].inbox + [msg];

      success := true;
    }

    // Receive a message from inbox
    method Receive() returns (msg: Message, success: bool)
      ensures success ==> msg == old(inbox)[0]
      ensures success ==> inbox == old(inbox)[1..]
      ensures !success ==> inbox == old(inbox)
