    // Broadcast message to all processes
    method Broadcast(content: string, processes: seq<Process>) returns (success: bool)
      requires |processes| > 0
      ensures forall i | 0 <= i < |processes| :: 
        success ==> processes[i].inbox == old(processes[i].inbox) + [Message(content, id, i, clock)]
      ensures success ==> outbox == old(outbox) + [Message(content, id, -1, clock)]  // -1 indicates broadcast
