    method Enqueue(msg: Message) returns (success: bool)
      ensures success ==> messages == old(messages) + [msg]
      ensures !success ==> messages == old(messages)
    {
      if |messages| >= capacity {
        success := false;
        return;
      }

      messages := messages + [msg];
      success := true;
    }

