  method LinearSearchHelper<T>(a: array<T>, p: T -> bool, index: int) returns (result: int)
    requires 0 <= index <= a.Length
    ensures -1 <= result < a.Length
    ensures result >= 0 ==> p(a[result])
    ensures result >= 0 ==> (forall i :: 0 <= i < result ==> !p(a[i]))
    ensures result == -1 ==> (forall i :: 0 <= i < a.Length ==> !p(a[i]))
    decreases a.Length - index
