  // Generic binary search function that maintains array invariants
  method BinarySearch<T(==)>(arr: array<T>, element: T) returns (index: int)
    requires arr != null
    requires forall i, j :: 0 <= i < j < arr.Length ==> arr[i] <= arr[j]  // arr is sorted
    ensures -1 <= index < arr.Length
