/**
 * LinearSearch method that searches for an element in an array
 * Returns the index of the element if found, -1 otherwise
 */
method LinearSearch(arr: array<int>, target: int) returns (index: int)
  requires arr != null
  ensures index == -1 || (0 <= index < arr.Length && arr[index] == target)
  ensures index == -1 ==> forall i :: 0 <= i < arr.Length ==> arr[i] != target
  ensures index != -1 ==> arr[index] == target
{
  index := -1;
  var i: int := 0;

  while i < arr.Length
    invariant 0 <= i <= arr.Length
    invariant index == -1 ==> forall j :: 0 <= j < i ==> arr[j] != target
    invariant index != -1 ==> (0 <= index < i && arr[index] == target)
  {
    if arr[i] == target {
      index := i;
      return;
    }
    i := i + 1;
  }
}

